// #0ce894493185e3148625643a — ссылка приглашения бизнеса в статусе חסום / נמחק (кейсы BIZ-INV-004…007).
// Данные: одноразовый бизнес «QA-AUTO-0ce8 …», создаётся Super Admin через admin-create-business вместе с
// приглашением первого מנהל חשבון (письмо на example.com не уходит — это нормально). Общий бизнес testim не трогается.
// По приглашению НЕ вступаем (нужен пароль). В конце бизнес удаляется (статус נמחק) — это и есть последний шаг проверки.
// ПОДМЕНА ОТВЕТА (route) — только в тесте карточки менеджера: настоящее приглашение от менеджера требует
// вступившего менеджера (пароль), поэтому к настоящему ответу get_invitation_by_token добавляется contact.
import * as path from 'path';
import { Browser, Page, Route } from '@playwright/test';
import { test, expect } from '../../fixtures';
import { SUPABASE_URL, openWithApi, runStamp } from '../support/api';

const ADMIN_STATE = path.resolve(__dirname, '../../../auth/admin.json');
test.use({ storageState: ADMIN_STATE });
test.describe.configure({ mode: 'serial' });

const stamp = runStamp();
const BUSINESS_NAME = `QA-AUTO-0ce8 ${stamp}`;
const FIRST_MANAGER = { full_name: `QA-AUTO מנהל ${stamp}`, email: 'qa+auto-0ce8@example.com' };
// Контакт для подмены — в формате, который сервер отдаёт для приглашения от менеджера.
const MANAGER_CONTACT = { role: 'account_manager', full_name: 'QA-AUTO מנהלת', email: 'qa-auto-0ce8-mgr@example.com' };

let businessId = '';
let token = '';
let deleted = false;

type InvitationPayload = Record<string, unknown> & { status?: string; contact?: unknown };

async function setStatus(page: Page, status: 'active' | 'blocked') {
  const api = await openWithApi(page, '/admin/businesses');
  const res = await api.rpc('admin_set_business_status', { p_business_id: businessId, p_status: status });
  expect(res.ok(), `admin_set_business_status ${status}: ${res.status()} ${await res.text()}`).toBeTruthy();
}

async function deleteViaUi(page: Page) {
  await page.goto(`/admin/businesses/${businessId}`);
  const status = page.getByRole('region', { name: 'סטטוס החשבון' });
  await status.getByRole('combobox', { name: 'סטטוס חדש' }).selectOption({ label: 'נמחק' });
  await status.getByRole('button', { name: 'עדכון סטטוס' }).click();
  await page.getByRole('button', { name: 'אישור', exact: true }).click();
  await expect(page.getByText('בית העסק נמחק')).toBeVisible();
  deleted = true;
}

/** Гость открывает ссылку приглашения; возвращает настоящий ответ get_invitation_by_token. */
async function openInvite(guest: Page): Promise<InvitationPayload> {
  const loaded = guest.waitForResponse((r) => r.url().includes('/rpc/get_invitation_by_token') && r.request().method() === 'POST');
  await guest.goto(`/invite/${token}`);
  const res = await loaded;
  expect(res.ok(), `get_invitation_by_token: ${res.status()}`).toBeTruthy();
  return (await res.json()) as InvitationPayload;
}

async function expectJoinForm(guest: Page, payload: InvitationPayload) {
  expect(payload.status).toBe('pending');
  await expect(guest.getByRole('heading', { level: 1, name: 'הצטרפות לחשבון העסק' })).toBeVisible();
  await expect(guest.getByText(BUSINESS_NAME)).toBeVisible();
  await expect(guest.getByRole('textbox', { name: 'סיסמה', exact: true })).toBeVisible();
  await expect(guest.getByRole('button', { name: 'הצטרפות לחשבון', exact: true })).toBeVisible();
}

/** Экран недоступной ссылки по AC: без формы и без данных бизнеса. */
async function expectInactiveScreen(guest: Page, payload: InvitationPayload) {
  // Источник: AC «…מציגה את מסך הקישור הלא זמין ללא טופס וללא פרטי העסק»; «מה רצוי» — «מציג מיד».
  expect(payload.status).toBe('unavailable');
  expect(JSON.stringify(payload), 'ответ не должен содержать имя бизнеса').not.toContain(BUSINESS_NAME);
  await expect(guest.getByRole('heading', { level: 1, name: 'החשבון העסקי אינו פעיל' })).toBeVisible();
  await expect(guest.getByTestId('invite-unavailable')).toHaveAttribute('data-reason', 'unavailable');
  await expect(guest.getByText('אינו פעיל כרגע')).toBeVisible();
  await expect(guest.getByRole('textbox')).toHaveCount(0);
  await expect(guest.getByRole('button', { name: 'הצטרפות לחשבון', exact: true })).toHaveCount(0);
  await expect(guest.getByText(BUSINESS_NAME)).toHaveCount(0);
  // Реджект 05.10 Р1 (бренд, 2 колонки) и Р4 (низ карточки).
  await expect(guest.getByText('סימולטור מכירות')).toBeVisible();
  await expect(guest.getByRole('link', { name: 'תנאי שימוש' })).toBeVisible();
  await expect(guest.getByRole('link', { name: 'מדיניות פרטיות' })).toBeVisible();
  await expect(guest.getByRole('link', { name: 'פנייה לתמיכה' }).last()).toHaveAttribute('href', /^mailto:/);
}

/** Приглашение от Super Admin: карточки менеджера нет, путь — через поддержку (комментарий программиста 08.10). */
async function expectSupportPath(guest: Page, payload: InvitationPayload) {
  expect(payload.contact ?? null, 'у приглашения от Super Admin нет контакта менеджера').toBeNull();
  await expect(guest.getByText('איך מקבלים הזמנה חדשה?')).toBeVisible();
  await expect(guest.getByText('לבירור מצב החשבון ולקבלת הזמנה חדשה אפשר לפנות לתמיכה.')).toBeVisible();
  await expect(guest.getByText('מי יכול לשלוח הזמנה חדשה')).toHaveCount(0);
  await expect(guest.getByRole('link', { name: /^כתיבה ל/ })).toHaveCount(0);
}

async function guestAt(browser: Browser, viewport: { width: number; height: number }) {
  const baseURL = test.info().project.use.baseURL;
  const ctx = await browser.newContext({ baseURL, locale: 'he-IL', viewport });
  return { ctx, page: await ctx.newPage() };
}

test.describe('Ссылка приглашения неактивного бизнеса (#0ce894493185e3148625643a)', () => {
  test.afterAll(async ({ browser }) => {
    if (!businessId || deleted) return;
    const ctx = await browser.newContext({ storageState: ADMIN_STATE, baseURL: test.info().project.use.baseURL });
    try {
      await deleteViaUi(await ctx.newPage());
    } finally {
      await ctx.close();
    }
  });

  test('активный бизнес — ссылка приглашения показывает форму вступления (контроль) @desktop @data #0ce894493185e3148625643a', async ({ page, asUser }) => {
    const api = await openWithApi(page, '/admin/businesses');
    const res = await page.request.post(`${SUPABASE_URL}/functions/v1/admin-create-business`, {
      headers: api.headers,
      data: {
        name: BUSINESS_NAME,
        industry: 'QA-AUTO',
        contact_name: 'QA-AUTO איש קשר',
        contact_role: 'QA',
        contact_phone: '0500000000',
        contact_email: 'qa+auto-0ce8-contact@example.com',
        first_manager: FIRST_MANAGER,
        default_language: 'he',
        status: 'active',
        internal_note: 'QA-AUTO: одноразовый бизнес автотеста #0ce89449, удаляется в конце',
      },
    });
    expect(res.ok(), `admin-create-business: ${res.status()} ${await res.text()}`).toBeTruthy();
    const created = (await res.json()) as { business_id: string; invitation: { token: string; status: string } };
    businessId = created.business_id;
    token = created.invitation.token;
    expect(businessId).toBeTruthy();
    expect(token).toBeTruthy();
    test.info().annotations.push({ type: 'test-data', description: `business ${BUSINESS_NAME} ${businessId} (удаляется в конце)` });

    const guest = await asUser('guest');
    await expectJoinForm(guest, await openInvite(guest));
  });

  test('бизнес חסום, приглашение от Super Admin — «החשבון העסקי אינו פעיל» без формы и имени бизнеса, путь через поддержку; 1440 и 375 @desktop @data #0ce894493185e3148625643a', async ({ page, browser }) => {
    expect(businessId, 'нужен бизнес из первого теста (serial)').toBeTruthy();
    await setStatus(page, 'blocked');

    for (const viewport of [{ width: 1440, height: 900 }, { width: 375, height: 812 }]) {
      const { ctx, page: guest } = await guestAt(browser, viewport);
      try {
        const payload = await openInvite(guest);
        await expectInactiveScreen(guest, payload);
        await expectSupportPath(guest, payload);
        const overflow = await guest.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth);
        expect(overflow, `горизонтальная прокрутка на ${viewport.width}`).toBeLessThanOrEqual(0);
      } finally {
        await ctx.close();
      }
    }
  });

  test('бизнес חסום, приглашение от менеджера (подмена ответа) — карточка «מי יכול לשלוח הזמנה חדשה», кнопка «כתיבה ל…» @desktop @data #0ce894493185e3148625643a', async ({ asUser }) => {
    expect(businessId, 'нужен заблокированный бизнес из предыдущего теста (serial)').toBeTruthy();
    const guest = await asUser('guest');
    let realStatus = '';
    await guest.route('**/rest/v1/rpc/get_invitation_by_token', async (route: Route) => {
      const response = await route.fetch();
      const json = (await response.json()) as InvitationPayload;
      realStatus = String(json.status);
      await route.fulfill({ response, json: { ...json, contact: MANAGER_CONTACT } });
    });
    const payload = await openInvite(guest);
    expect(realStatus, 'настоящий ответ сервера для заблокированного бизнеса').toBe('unavailable');
    await expectInactiveScreen(guest, payload);

    // Реджект 05.10 Р2/Р3, Figma 733:1408: имя, роль · кто пригласил, почта; кнопка «כתיבה ל<имя>».
    const card = guest.getByTestId('new-invite-contact');
    await expect(card.getByText('מי יכול לשלוח הזמנה חדשה')).toBeVisible();
    await expect(card.getByText(MANAGER_CONTACT.full_name, { exact: true })).toBeVisible();
    await expect(card.getByText('מנהל/ת חשבון · הזמין/ה אתכם')).toBeVisible();
    await expect(card.getByText(MANAGER_CONTACT.email)).toBeVisible();
    const write = guest.getByRole('link', { name: `כתיבה ל${MANAGER_CONTACT.full_name}` });
    await expect(write).toBeVisible();
    await expect(write).toHaveAttribute('href', /^mailto:/);
    await expect(write).toHaveAttribute('href', /qa-auto-0ce8-mgr/);
    await expect(guest.getByText('איך מקבלים הזמנה חדשה?')).toHaveCount(0);
  });

  test('после разблокировки бизнеса ссылка приглашения снова показывает форму @desktop @data #0ce894493185e3148625643a', async ({ page, asUser }) => {
    expect(businessId, 'нужен бизнес из первого теста (serial)').toBeTruthy();
    await setStatus(page, 'active');
    const guest = await asUser('guest');
    await expectJoinForm(guest, await openInvite(guest));
  });

  test('бизнес נמחק — «החשבון העסקי אינו פעיל» без формы и имени бизнеса @desktop @data #0ce894493185e3148625643a', async ({ page, asUser }) => {
    expect(businessId, 'нужен бизнес из первого теста (serial)').toBeTruthy();
    await deleteViaUi(page);
    const guest = await asUser('guest');
    const payload = await openInvite(guest);
    await expectInactiveScreen(guest, payload);
    await expectSupportPath(guest, payload);
  });
});
